import * as T from '../store/vendor/three.module.min.js';
import {loadCoastArt,coastGeometry,treeRecords,rockRecords,rockGeometry,WATER_LEVEL} from './coast-world.mjs';
import {drawProjectedShore} from './photo-shores.mjs';
const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),camera=new T.PerspectiveCamera(),mod=(a,b)=>((a%b)+b)%b;
let width=390,height=430,time=0,art,back;const terrain=[];
for(const side of [-1,1])for(let k=0;k<3;k++)terrain.push({g:coastGeometry(side,k,32),base:130+k*260});
const trees=treeRecords(),rocks=rockRecords(),rockShapes=[0,1,2].map(rockGeometry);
function project(x,y,z){const p=new T.Vector3(x,y,z).project(camera);return{x:(p.x*.5+.5)*width,y:(-.5*p.y+.5)*height,z:p.z};}
function triangle(p,uv,pattern,shade=0){if(p.some(a=>a.z>1||a.z<-1))return;const [a,b,c]=p,[u,v,w]=uv,det=(v.x-u.x)*(w.y-u.y)-(w.x-u.x)*(v.y-u.y);if(Math.abs(det)<.0001)return;ctx.save();ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.closePath();ctx.clip();const ax=((b.x-a.x)*(w.y-u.y)-(c.x-a.x)*(v.y-u.y))/det,bx=((b.y-a.y)*(w.y-u.y)-(c.y-a.y)*(v.y-u.y))/det,cx=((c.x-a.x)*(v.x-u.x)-(b.x-a.x)*(w.x-u.x))/det,dx=((c.y-a.y)*(v.x-u.x)-(b.y-a.y)*(w.x-u.x))/det;ctx.transform(ax,bx,cx,dx,a.x-ax*u.x-cx*u.y,a.y-bx*u.x-dx*u.y);ctx.fillStyle=pattern;ctx.fillRect(Math.min(u.x,v.x,w.x)-2,Math.min(u.y,v.y,w.y)-2,Math.max(u.x,v.x,w.x)-Math.min(u.x,v.x,w.x)+4,Math.max(u.y,v.y,w.y)-Math.min(u.y,v.y,w.y)+4);ctx.restore();if(shade){ctx.fillStyle=`rgba(10,23,15,${shade})`;ctx.fill();}}
function render(){if(!art||!back)return;const d=2;canvas.width=width*d;canvas.height=height*d;canvas.style.width=width+'px';canvas.style.height=height+'px';ctx.setTransform(d,0,0,d,0,0);ctx.imageSmoothingQuality='high';const portrait=width/height<.85;camera.fov=portrait?65:57;camera.aspect=width/height;camera.near=.1;camera.far=1400;camera.position.set(0,portrait?10.5:9.6,portrait?-21:-15.8);camera.lookAt(0,7.6,35);camera.updateProjectionMatrix();camera.updateMatrixWorld();ctx.fillStyle='#93afbd';ctx.fillRect(0,0,width,height);drawProjectedShore(ctx,canvas,camera,{canvas:back,pose:{x:0,y:100,z:650,width:1400,height:933}},width,height);
 const travel=time*15,draw=[],grass=ctx.createPattern(art.ground,'repeat'),granite=ctx.createPattern(art.granite,'repeat');
 for(const {g,base}of terrain){const p=g.attributes.position,uv=g.attributes.uv,weights=g.attributes.coastWeights,idx=g.index.array,offset=mod(base-travel+130,780)-130;for(let i=0;i<idx.length;i+=3){const ids=[idx[i],idx[i+1],idx[i+2]],z=ids.reduce((s,j)=>s+p.getZ(j)+offset,0)/3,y=ids.reduce((s,j)=>s+p.getY(j),0)/3;if(z<0||z>570||y<WATER_LEVEL+.03)continue;const rock=ids.reduce((s,j)=>s+weights.getX(j),0)/3>.42;draw.push({z,fn:()=>triangle(ids.map(j=>project(p.getX(j),p.getY(j),p.getZ(j)+offset)),ids.map(j=>({x:uv.getX(j)*(rock?.75:1)*(rock?art.granite.width:art.ground.width),y:(1-uv.getY(j))*(rock?.75:1)*(rock?art.granite.height:art.ground.height)})),rock?granite:grass,.19)});}}
 for(const r of trees){const z=mod(r.z-travel+130,780)-130;if(z<0||z>600)continue;draw.push({z,fn:()=>{const foot=project(r.x,r.y,z),tip=project(r.x,r.y+r.h,z),im=art.trees[r.variant],h=foot.y-tip.y,w=h*im.width/im.height;if(foot.x+w<0||foot.x-w>width||h<1)return;ctx.globalAlpha=Math.max(.45,1-z*.00065);ctx.drawImage(im,foot.x-w/2,tip.y,w,h);ctx.globalAlpha=1;}});}
 for(const r of rocks){const z=mod(r.z-travel+130,780)-130;if(z<0||z>400)continue;const g=rockShapes[r.variant],p=g.attributes.position,uv=g.attributes.uv,c=Math.cos(r.angle),s=Math.sin(r.angle);for(let i=0;i<p.count;i+=3){const ids=[i,i+1,i+2];draw.push({z:z+ids.reduce((a,j)=>a+p.getZ(j)*r.size,0)/3,fn:()=>triangle(ids.map(j=>{const x=p.getX(j)*r.size*1.45,q=p.getZ(j)*r.size*1.1;return project(r.x+x*c+q*s,r.y+p.getY(j)*r.size*.75,z+q*c-x*s);}),ids.map(j=>({x:uv.getX(j)*art.granite.width,y:(1-uv.getY(j))*art.granite.height})),granite,.15)});}}
 draw.sort((a,b)=>b.z-a.z);for(const item of draw)item.fn();document.querySelector('#status').textContent=`Ready · ${time}s · ${trees.length} grounded trees · 120 shoreline rocks · actual coast geometry`;
}
Promise.all([loadCoastArt(),new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.src='art/fjord-v45.webp';})]).then(([a,b])=>{art=a;back=b;render();}).catch(e=>{document.querySelector('#status').textContent='Asset load failed: '+e.message;});
document.querySelector('#phone').onclick=()=>{width=390;height=430;render();};document.querySelector('#wide').onclick=()=>{width=1100;height=600;render();};document.querySelector('#move').onclick=()=>{time+=5;render();};
